export const program=[['CALL','extract'],['LOAD',6],['SUB',5],['JNEG','keep'],['LOAD',6],['STORE',5],['label','keep'],['LOAD',3],['STORE',0],['LOAD',4],['SUB',2],['STORE',4],['JZERO','done'],['JUMP',0],['label','done'],['HALT'],['label','extract'],['LOAD',0],['STORE',6],['LOAD',7],['STORE',3],['label','divide'],['LOAD',6],['SUB',1],['JNEG','return'],['STORE',6],['LOAD',3],['ADD',2],['STORE',3],['JUMP','divide'],['label','return'],['RETURN']];
export function assemble(source){const labels={};let pc=0;for(const[op,arg]of source)op==='label'?labels[arg]=pc:pc++;return source.filter(([op])=>op!=='label').map(([op,arg])=>[op,typeof arg==='string'?labels[arg]:arg]);}
export const instructions=assemble(program);
export function createMachine(word=0x012b){if(!Number.isInteger(word)||word<0||word>65535)throw new RangeError('Use a 16-bit unsigned input word.');return{ac:0,pc:0,memory:[word,16,1,0,4,0,0,0],stack:[],halted:false,cycles:0,last:null};}
export function step(m,code=instructions){if(m.halted)return m;const instruction=code[m.pc];if(!instruction)throw new RangeError('PC outside program.');const[op,arg]=instruction;const before=m.ac;m.pc++;const read=()=>{if(!Number.isInteger(arg)||arg<0||arg>=m.memory.length)throw new RangeError('Invalid memory address.');return m.memory[arg];};
  switch(op){case'LOAD':m.ac=read();break;case'STORE':read();m.memory[arg]=m.ac;break;case'ADD':m.ac+=read();break;case'SUB':m.ac-=read();break;case'JUMP':m.pc=arg;break;case'JNEG':if(m.ac<0)m.pc=arg;break;case'JZERO':if(m.ac===0)m.pc=arg;break;case'CALL':m.stack.push(m.pc);m.pc=arg;break;case'RETURN':if(!m.stack.length)throw new Error('Empty return stack.');m.pc=m.stack.pop();break;case'HALT':m.halted=true;break;default:throw new Error('Unknown instruction.');}
  m.cycles++;m.last={op,arg,before,operand:op==='SUB'?m.memory[arg]:null,after:m.ac};return m;
}
